def all_same_type(t):
    """
    Return True if all elements in tuple t have the same type, False otherwise.
    Handles empty and single-element tuples as True.
    """
    if len(t) <= 1:
        return True  # trivially same type

    first_type = type(t[0])
    for elem in t[1:]:
        if type(elem) != first_type:
            return False
    return True
